!function(e){function i(i){for(var t,p,n=i[0],g=i[1],s=i[2],o=0,I=[];o<n.length;o++)p=n[o],Object.prototype.hasOwnProperty.call(r,p)&&r[p]&&I.push(r[p][0]),r[p]=0;for(t in g)Object.prototype.hasOwnProperty.call(g,t)&&(e[t]=g[t]);for(d&&d(i);I.length;)I.shift()();return a.push.apply(a,s||[]),m()}function m(){for(var e,i=0;i<a.length;i++){for(var m,p=a[i],n=!0,g=1;g<p.length;g++)m=p[g],0!==r[m]&&(n=!1);n&&(a.splice(i--,1),e=t(t.s=p[0]))}return e}function t(i){if(p[i])return p[i].exports;var m=p[i]={i:i,l:!1,exports:{}};return e[i].call(m.exports,m,m.exports,t),m.l=!0,m.exports}var p={},r={35:0},a=[];t.m=e,t.c=p,t.d=function(e,i,m){t.o(e,i)||Object.defineProperty(e,i,{enumerable:!0,get:m})},t.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},t.t=function(e,i){if(1&i&&(e=t(e)),8&i)return e;if(4&i&&"object"==typeof e&&e&&e.__esModule)return e;var m=Object.create(null);if(t.r(m),Object.defineProperty(m,"default",{enumerable:!0,value:e}),2&i&&"string"!=typeof e)for(var p in e)t.d(m,p,function(i){return e[i]}.bind(null,p));return m},t.n=function(e){var i=e&&e.__esModule?function(){return e.default}:function(){return e};return t.d(i,"a",i),i},t.o=function(e,i){return Object.prototype.hasOwnProperty.call(e,i)},t.p="";var n=window.webpackJsonp=window.webpackJsonp||[],g=n.push.bind(n);n.push=i,n=n.slice();for(var s=0;s<n.length;s++)i(n[s]);var d=g;a.push([52,0]),m()}({52:function(e,i,m){"use strict";m.r(i);var t=m(0);Object(t.a)("de","army",m(53),m(1))},53:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"自行火炮","link":"de_army#de_army_spgun"}],"model":"Ⅲ号自行突击炮车","description":"<p>Ⅲ号自行突击炮车是德军在Ⅲ号坦克的底盘上所开发的一种步兵火力支援炮车，它主要是伴随步兵进攻作战，用于摧毁敌方的坦克、碉堡、反坦克火炮和机枪火力点。</p><p>Ⅲ号自行突击炮车在1940年1月正式投入生产，先后生产有A、B、C/D、F、F/8和G等多种型号，其中1940年至1941年生产的突击炮车装备Stuk L/24 75mm短身管火炮，编号为Sd kfz 142；1941年至1942年生产的突击炮车装备Stuk L/43 75mm短身管火炮，编号为Sd kfz 142/1；而1942年至1945年生产的突击炮车装备Stuk L/48 75mm长身管火炮，编号也是Sd kfz 142/1；后期还生产了一种突击炮车装备了105mm火炮，编号是Sd kfz 142/2。</p><p>Ⅲ号自行突击炮车是德军在二战期间装备的一种较优秀的自行炮车，它机动性能好，车身低矮目标小，防护也较好，且它的结构较简单，因此得到大量生产，二战期间，一共生产了约9500多辆Ⅲ号自行突击炮车，其中以G型产量最多（7700多辆)。Ⅲ号自行突击炮车由于数量众多，战绩不错，作战性能比坦克还略有优势，因此成为了整个二战中德军的主力装甲战车，其身影遍及欧洲东线、西线各个战场及北非战场。</p>","part1title":"","part1description":"","part1content":[{"image":"{{text}}Ⅲ号A型自行突击炮车四视图{{image}}imgs/de/army/de_army_spgunIII_11.jpg","description":"<h6>Ⅲ号A型自行突击炮车<br>型号：Sd.Kfz.142 Sturmgeschϋtz Ⅲ Ausf.A</h6><p>A型是Ⅲ号自行突击炮车最早开始量产型号，它采用Ⅲ号坦克F型底盘，将Stuk L/24 75mm短身管火炮直接安装在车身上，战斗室为全封闭式，整车高度只有1人的身高。1940年1月至5月共生产了30辆，装备了德军一个独立突击炮连，参加了入侵法国的战斗。</p>","caption":""},{"image":"{{text}}Ⅲ号B型自行突击炮车四视图{{image}}imgs/de/army/de_army_spgunIII_12.jpg","description":"<h6>Ⅲ号B型自行突击炮车<br>型号：Sd.Kfz.142 Sturmgeschϋtz Ⅲ Ausf.B</h6><p>B型是Ⅲ号自行突击炮车的真正量产型号，它对炮车的传动系统进行了改进，采用了新型的变速器，履带宽度也增宽了，链齿轮也作了改动，加强了炮车行驶的可靠性和稳定性，其行驶最高速度可达40km/h。该型炮车依然安装Stuk L/24 75mm短身管火炮，1940年6月至1942年5月共生产了320辆，装备了德军一个的独立突击炮营，先后参加了巴尔干战役和入侵苏联的战斗。</p>","caption":""},{"image":"{{text}}Ⅲ号C/D型自行突击炮车{{image}}imgs/de/army/de_army_spgunIII_13.jpg","description":"<h6>Ⅲ号C/D型自行突击炮车<br>型号：Sd.Kfz.142 Sturmgeschϋtz Ⅲ Ausf.C/D</h6><p>C/D型Ⅲ号自行突击炮车是继B型后续开发的量产型号，它对炮车的战斗室进行了改造，在战斗室的上方安装了潜望式瞄准器，替代了原来战斗室前部的瞄准孔，从而提高了射击的准确性，同时也提高了战斗室的正面防护。炮车依然安装Stuk L/24 75mm短身管火炮。</p><p>1940年5月至9月共生产了50辆C型和150辆D型Ⅲ号自行突击炮车。</p>","caption":""},{"image":"{{text}}Ⅲ号E型自行突击炮车四视图{{image}}imgs/de/army/de_army_spgunIII_14.jpg","description":"<h6>Ⅲ号E型自行突击炮车<br>型号：Sd.Kfz.142 Sturmgeschϋtz Ⅲ Ausf.E</h6><p>E型Ⅲ号自行突击炮车扩大了战斗室，除了安装了一个无线电装甲盒子外，还增带了8发炮弹（一共52发），此外该型炮车还新装了一挺MG34机枪，使整车战斗力得到加强。E型是最后一种安装Stuk L/24 75mm短身管火炮的Ⅲ号自行突击炮车。</p><p>1941年9月至1942年3月一共生产了272辆E型Ⅲ号自行突击炮车。</p>","caption":""},{"image":"{{text}}Ⅲ号F型自行突击炮车四视图{{image}}imgs/de/army/de_army_spgunIII_15.jpg","description":"<h6>Ⅲ号F型自行突击炮车<br>型号：Sd.Kfz.142/1 Sturmgeschϋtz Ⅲ Ausf.F</h6><p>Ⅲ号F型自行突击炮车是在E型底盘上改装的，初期安装了43倍口径的75mm StuG 40型长身管火炮，该火炮可以从1000米外击穿30度倾角厚82mm的钢板；后期则换装了威力更大的48倍口径的75mm StuG 40型长身管火炮，该火炮可以从1000米外击穿30度倾角厚97mm的钢板。后期生产的F型自行突击炮车还在车身前方加装了30mm的装甲，改装后的Ⅲ号F型自行突击炮车火力与防护力大大增强，在东线战场与苏军的T-34和KV-1坦克对抗中不落下风。</p><p>F型自行突击炮车在1942年3月至9月间一共生产了364辆。</p>","caption":""},{"image":"{{text}}Ⅲ号F/8型自行突击炮车四视图{{image}}imgs/de/army/de_army_spgunIII_16.jpg","description":"<h6>Ⅲ号F/8型自行突击炮车<br>型号：Sd.Kfz.142/1 Sturmgeschϋtz Ⅲ Ausf.F/8</h6><p>Ⅲ号F/8型自行突击炮车是Ⅲ号自行突击炮车第8期的生产批号，它采用了Ⅲ号坦克J、M、N型的底盘，车身比F型略长，安装了48倍口径的75mm StuG 40型长身管火炮，车前装甲增加到50mm厚，防护力得到了加强。</p><p>F/8型自行突击炮车在1942年9月至12月间一共生产了334辆。主要装备德军各集团军下属的独立突击炮营，同时“帝国”师和“骷髅”师也配备了一个由F/8突击炮车组成的突击炮营。</p>","caption":""},{"image":"{{text}}Ⅲ号G型自行突击炮车四视图{{image}}imgs/de/army/de_army_spgunIII_17.jpg","description":"<h6>Ⅲ号G型自行突击炮车<br>型号：Sd.Kfz.142/1 Sturmgeschϋtz Ⅲ Ausf.G</h6><p>Ⅲ号G型自行突击炮车是以Ⅲ号坦克底盘制作的突击炮车系列的最后一个型号，该型炮车生产时间长，产量也多，从1942年12月至1945年3月，一共生产了7720辆。</p><p>G型自行突击炮车在生产过程中不断进行改进，初期G型炮车加宽了上部车体和战斗室，战斗室顶盖左侧增设了车长指挥室，使车长视野更开阔，并为顶部机枪加装了防盾，部分炮车还安装了三联装烟雾弹发射器，中期G型炮车将车体前部装甲改进为80mm厚的一体装甲，大大加强了炮车前部的防护力；而后期G型炮车将方形火炮防盾改为圆弧形防盾（猪头形防盾，这也是后期型的最大外形特点），提高了火炮的防护能力和车长指挥室的防弹能力。</p>","caption":""},{"image":"{{text}}1944年冬季，在东线匈牙利地区，隶属德国武装党卫军第8师的一辆安装了105mm口径火炮的42型Ⅲ号自行突击炮车。{{image}}imgs/de/army/de_army_spgunIII_18.jpg","description":"<h6>42型Ⅲ号自行突击炮车<br>型号：Sd.Kfz.142/2 105mm Sturmgeschϋtz Ⅲ</h6><p>为了拥有更大威力的火炮来对抗苏军与盟军的坦克，1942年10月，德军在10辆F型和F/8型自行突击炮车底盘上安装了105mm口径的火炮，经测试成功后。在1943年3月开始量产，该突击炮车称为StuH 42型自行突击炮车。这种炮车从1942年10月至1945年2月，一共生产了1211辆。</p>","caption":""}],"part2title":"战场上的Ⅲ号自行突击炮车","part2description":"1941年4月，配备A型Ⅲ号自行突击炮车的德国党卫军“警卫旗队”旅下属的第5突击炮连和“帝国”师下属的突击炮连一起参加了巴尔干战役，由于战绩突出，1942年，德军又组建了多个党卫军突击炮营；1943年起，德军党卫军的装甲营和坦克歼击营都基本上配备了Ⅲ号自行突击炮车。面在德国陆军部队中，除了在每个坦克歼击营中配备一个突击炮车连外，还将Ⅲ号自行突击炮车配属到步兵团和步兵营，除了支援步兵进攻外，还担负了反坦克作战。1944年，随着Ⅲ号自行突击炮车生产数量的增加，德军的山地师、掷弹兵师和步兵师下属的突击炮连升级为突击炮营。此外还有部分Ⅲ号自行突击炮车配备到德国空军的地面部队中。</p><p>Ⅲ号自行突击炮车在战场上表现是很不错的，但面对苏军与盟军日益强大的反坦克炮火和威力强劲的坦克，后期在战场上损失也是极大的。","part2content":[{"image":"imgs/de/army/de_army_spgunIII_21.jpg","description":"Ⅲ号自行突击炮车油画作品","caption":""},{"image":"imgs/de/army/de_army_spgunIII_22.jpg","description":"1940年5月，法国战场，德军某突击炮营的一辆Ⅲ号A型自行突击炮车，由于该型炮车在法国战场取得不错的战绩，后来德军就对Ⅲ号自行突击炮车不断改进并大量生产。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_23.jpg","description":"1941年10月，东线苏联战场，在莫斯科地区的德军201突击炮营一辆编号205的Ⅲ号C型自行突击炮车。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_24.jpg","description":"东线苏联战场，一辆隶属德军226突击炮营的Ⅲ号E型自行突击炮车。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_25.jpg","description":"1944年4月，东线波兰科韦利（Kovel）地区，一辆德军不明单位的Ⅲ号F/8型自行突击炮车。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_26.jpg","description":"1943年3月，东线苏联哈尔科夫战场，隶属德军“阿道夫·希特勒警卫旗队”装甲掷弹兵师的一辆Ⅲ号G型（前期生产）突击炮车。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_27.jpg","description":"1944年1月，东线苏联乌克兰战场，隶属德军“大德意志”突击炮旅的一辆Ⅲ号G型（前期生产）突击炮车。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_28.jpg","description":"1945年2月，在Reichwald地区，隶属德军第12突击炮旅，由Deutsch中尉指挥的一辆Ⅲ号G型（后期生产）突击炮车。据称在1945年3月24日至4月24日的一个月时间时，由“Deutsch”中尉指挥的Ⅲ号G型自行突击炮车一共歼灭了44辆盟军坦克。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_29.jpg","description":"出现在Vire战场上的一辆隶属德军394突击炮旅的StuH 42型（Sd.Kfz.142/2）自行突击榴弹炮车；该辆炮车安装了105mm口径的L28型榴弹炮。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_30.jpg","description":"1941年秋，在德军入侵苏联的巴巴罗萨行动中，一辆德军Ⅲ号B型自行突击炮车正行驶在苏联大地上。此时德军正迅速向苏联深纵迫进，Ⅲ号自行突击炮车起了很大作用。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_31.jpg","description":"1943年秋，东线苏联战场，在库尔斯克北部地区作战的一辆德军Ⅲ号G型自行突击炮车（前期型）。从该车两侧临时加装附加装甲的凌乱可知当时战斗的激烈。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_32.jpg","description":"东线苏联战场，一辆正在与步兵一起行进的Ⅲ号B型自行突击炮车。这辆III号B型自行突击炮车曾被误认为是A型。但从其最前方的复位回动轮间距，可以明显看出它是B型车。同时其早期型传动链轮，36cm窄履带，窄驱动轮（注意其车身上的备用轮）符合其B型车基本配置，在履带装甲板后方的配载块也符合一些早期型的B型车特征。注意，这辆跑车上没有安装Notek灯火管制行驶头灯，还缺少了中部的回动轮。该车在其涂有深灰色底漆的车身上标识了一个白边十字徽标。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_33.jpg","description":"1941年，东线苏联战场，一辆隶属德军192突击炮团的Ⅲ号B型自行突击炮车正穿越大草原，掩护步兵攻击战斗，车旁伴随着一名拿着MG34机关枪的步兵。在炮车前部装甲板上标有这支部队的浅色“十字骷髅”徽标和履带式自走炮的战术标志。另外，该炮车的履带装甲板上还带了用于通过战壕的木条以及一些其它物品，车前位于履带装甲板近处还加装了履带式防护栅。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_34.jpg","description":"1941年秋，东线苏联战场，由于恶劣天气带来的泥泞路况和大雨，图中这辆第192突击炮团的III号B型自行突击炮车正与一队步兵配合作进攻姿态，为战地摄影师做摆拍，以达到战事宣传目的。在这辆跑车前甲板上的战术标号下方印有这支部队的浅色“十字骷髅”徽标。而放置在履带装甲上的木条（主要用于应付苏联境内的恶劣路况和反战壕之用）也算是这支部队的特色标志之一。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_35.jpg","description":"东线苏联战场，在冬季作战的一辆德军Ⅲ号C/D型自行突击炮车。这辆已在战斗中受损的炮车正引领着一队轮式装甲车辆（包括1辆20mm Sd.Kfz.222轻型装甲侦察车，1辆Sd.Kfz.260电台通信装甲车和1辆Sd.Kfz.221装甲侦察车）行进，同时还有一队德军士兵。这辆突击炮车在其白色车身上覆盖了杂色伪装网，缺了一截履带防护板，前甲板上有其战场编号字母“A”。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_36.jpg","description":"东线苏联战场，与德军一队电台兵一同行进的两辆德军Ⅲ号E型自行突击炮车。图片近处的突击炮被识别为E型是因为炮台右方也安装了附加的装甲电台篮筐，在之前的型号中此附加装备一般只安装在炮台左方，而随着战争加剧，德军的供应状况逐步变得恶劣，因此许多战斗车辆都开始自身携带大量的备用装备和消耗品，这辆在引擎舱上带上了备用履带和用于固定零散物件的杂物篮的突击炮车也凸显了这种趋势。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_37.jpg","description":"东线苏联战场，正在掩护一队步兵作战的一辆德军Ⅲ号F型自行突击炮车。该车采用了后期型双导向瓶形炮口制退器的StuK40火炮。从图片中也可以看到其炮台顶部上凸起的大型抽烟器风扇罩；这辆突击炮车被识别为F型是因其车后上部所安装的后方装甲板。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_38.jpg","description":"东线苏联战场，正在待命的一辆德军Ⅲ号F型自行突击炮车。这辆III号F型突击炮安装有2架天线，应该是一辆指挥车。被识别为F型是因其长身管StuK40 L/48火炮（炮口并没有炮口制退器，很有可能是在进行改进测试）和前车身上的早期型拖车钩，而后期F/8型是基于J型车身（其拖车钩挂载点延伸出了前车身侧面装甲板）。图片中，在那两个士兵之间的炮台乘员舱上还可看到在F型和F/8型都配备的大型圆拱顶换气扇。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_39.jpg","description":"一群德国空军军官聚集在一辆III号F（或F/8）（根据该炮车的炮台顶部突出的排气管风扇罩可识别为F系列）型自行突击炮车前讨论，这些军官很有可能来自于“赫尔曼·戈林”师。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_40.jpg","description":"这是一辆德军Ⅲ号G型自行突击炮车。这辆III号G型自行突击炮车最独特的地方是它的三管烟雾弹发射器安装在炮台边的前方边缘一侧，此类安装方式仅采用了短短一段时间，然后便因使用方的投诉而被取消了，其原因主要是要在其车身的相应位置上需安装30mm复合装甲板以增加自身防护力。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_41.jpg","description":"这幅图片看起来发生在西线战场的某一个小镇，一名手持一具反坦克火箭筒的士兵从3辆III号G型自行突击炮车前面冲过。这种突击炮车是埃克特（Alkett）公司采用齐默尔特（Zimmerit，德国发明的一种防磁装甲材料）多层装甲板制造的盔盖式装甲车辆。最前方的那辆G式突击炮前部多处安装了单片80mm厚装甲板，在驾驶员观察窗口上方有螺栓固定的30mm厚复合装甲板（这是因其观察窗口处采用的是50mm厚装甲）。最后还需要注意的是在其斜装甲翻盖下方的外部挂锁，以及焊接在车长前方观察口的圆顶防盾和缺少了装甲裙板。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_42.jpg","description":"一辆准备出发、伴随步兵前进的III号G型自行突击炮车，其与基础型号的区别是，除了包括螺栓固定的复合装甲板，配备防盾的MG34机枪，焊接跑塔等，其他较为不常见的改进部分包括，炮台两侧的三管烟雾弹发射器，40cm履带上的中部履带齿。其车组在炮台两侧还增加了薄钢板和备用履带作为增强防护。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_43.jpg","description":"跟随在MG42机枪组后、在灌木丛中开路的一辆III号F型自行突击炮车。其被识别为F型是因其前车身上配备的的铸铁螺杆式拖车勾。注意其炮台前部一侧采用多色调迷彩的战场编号字母“F”。它未被包裹的炮口可以猜测其正进行着或刚刚完成了一次作战行动，而从那些步兵的表情上来看，更可能是后者（完成了一次作战行动）。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_44.jpg","description":"正在等待新命令的一辆StuG IIIG型突击炮。这辆晚期型的G型车可能是辆新车，状况良好。这可从它炮台前方装甲板上携带的一大段新的备用履带看出来。一个德军通讯兵正驾驶一辆摩托车在车旁驶过。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_45.jpg","description":"西线战场上一辆被盟军击毁的德军Ⅲ号G型自行突击炮车（前期生产型），一名被击毙的德军士兵挂在炮管上，旁边站着2名美军士兵。","caption":""},{"image":"imgs/de/army/de_army_spgunIII_46.jpg","description":"两名美军正驾驶一辆缴获的德军Ⅲ号G型自行突击炮车（后期生产）行进。","caption":""}]}')}});